// Extract just the data array from the wrapper
const input = $input.first().json;

// Handle if input is array or object
const dataArray = Array.isArray(input) ? input[0].data : input.data;

// Return each review as a separate item
return dataArray.map(review => ({
  json: {
    reviewId: review.id,
    type: review.type,
    rating: review.attributes.rating,
    title: review.attributes.title,
    body: review.attributes.body,
    reviewerNickname: review.attributes.reviewerNickname,
    createdDate: review.attributes.createdDate,
    territory: review.attributes.territory,
    hasResponse: review.relationships?.response?.data !== null,
    rawData: review
  }
}));

// Compile final response with all data
const aiResponse = $input.first().json;
const sentimentData = $('Parse Sentiment1').first().json;
const reviewData = $('Loop Over Items').context.noItemsLeft ? $('Loop Over Items').first().json : $input.first().json;

try {
  let content = aiResponse.content || aiResponse.message?.content || aiResponse.choices?.[0]?.message?.content;

  if (!content) {
    throw new Error('No content found in OpenAI response');
  }

  content = content.trim();

  // Return complete data structure
  return [{
    json: {
      // Review Information
      review_id: sentimentData.review_id,
      review_title: sentimentData.review_title,
      review_body: sentimentData.review_body,
      review_rating: sentimentData.review_rating,
      review_date: sentimentData.review_date,
      reviewer_nickname: sentimentData.reviewer_nickname,
      territory: sentimentData.territory,

      // Sentiment Analysis
      sentiment: sentimentData.sentiment,
      category: sentimentData.category,
      key_issues: sentimentData.key_issues,
      urgency: sentimentData.urgency,
      summary: sentimentData.summary,
      response_tone: sentimentData.response_tone,
      action_required: sentimentData.action_required,
      customer_emotion: sentimentData.customer_emotion,

      // Generated Response
      suggested_response: content,
      response_generated_at: new Date().toISOString(),

      // Platform
      platform: 'apple_app_store'
    }
  }];
} catch (error) {
  return [{
    json: {
      error: 'Failed to parse response generation',
      details: error.message,
      raw_response: aiResponse
    }
  }];
}

