const crypto = require('crypto');

return $input.all().map(item => {
  const reviewName = item.json.reviewer_nickname;  // correct field name from your schema
  const timestamp = item.json.response_generated_at;

  const id = crypto
    .createHash('sha256')
    .update(`${timestamp}${reviewName}`)
    .digest('hex')
    .substring(0, 32);

  return { json: { ...item.json, id } };
});

const crypto = require('crypto');

return $input.all().map(item => {
  const data = item.json;

  // Convert last_modified {seconds, nanos} → ISO timestamp string
  const seconds = parseInt(data.last_modified.seconds);
  const nanos = data.last_modified.nanos || 0;
  const last_modified = new Date(seconds * 1000 + nanos / 1000000).toISOString();

  // Generate ID
  const id = data.id || crypto
    .createHash('sha256')
    .update(`${data.response_generated_at}${data.author_name}`)
    .digest('hex')
    .substring(0, 32);

  return {
    json: {
      ...data,
      last_modified,  // overwrite the nested object with flat ISO string
      id
    }
  };
});

