const jwt = require('jsonwebtoken');

// Load credentials from n8n environment variables
const issuerID = $env.APPLE_ISSUER_ID;
const keyID = $env.APPLE_KEY_ID;
const privateKey = $env.APPLE_PRIVATE_KEY;

// Validate that all required environment variables are set
if (!issuerID || !keyID || !privateKey) {
  throw new Error('Missing required environment variables: APPLE_ISSUER_ID, APPLE_KEY_ID, or APPLE_PRIVATE_KEY');
}

const token = jwt.sign(
  {
    iss: issuerID,
    exp: Math.floor(Date.now() / 1000) + (20 * 60),
    aud: 'appstoreconnect-v1'
  },
  privateKey,
  {
    algorithm: 'ES256',
    header: {
      alg: 'ES256',
      kid: keyID,
      typ: 'JWT'
    }
  }
);

return [{ json: { token } }];
